"""CRE-T024..T026 — versioned, frozen benchmark (golden + holdout) and independent execution. Model-free.

* Suites are protected manifests (tests/reliability/{benchmark,holdout}/suite.yaml) generated by `freeze` from the
  definitions below: every case pins inputs (SHA-256), harness (SHA-256), compiler version/flags, safety profile and
  an oracle (SHA-256 of its canonical form) and validates against benchmark-case.schema.json.
* The runner reads oracles and fixtures from ITS revision; the revision under test only provides forge_factory on
  PYTHONPATH (isolated worktree). Unpinned or tampered cases are INCOMPLETE, tool drift is NOT_COMPUTABLE - neither
  ever becomes PASS (AT-021, AT-022). The harness reports observations; the runner evaluates the oracle (AT-023).
"""
from __future__ import annotations

import json
import shutil
import subprocess
import sys
import time
from pathlib import Path

import yaml

