def _tool_version(argv: list[str]) -> str:
    try:
        out = subprocess.run(argv, capture_output=True, text=True, timeout=20)
        return (out.stdout or out.stderr).strip().splitlines()[0][:120]
    except (OSError, subprocess.SubprocessError, IndexError):
        return "MISSING"


def _case_schema():
    from jsonschema import Draft202012Validator

    return Draft202012Validator(json.loads((CRE_CONTRACTS_DIR / "benchmark-case.schema.json").read_text()))


def freeze(kind: str, root: Path = REPO_ROOT) -> dict:
    """Maintenance command (oracle change => its own commit): pin hashes and tool versions into the suite file."""
    suite_dir = SUITES[kind].parent
    clang = _tool_version(["clang", "--version"])
    cases = []
    for d in DEFINITIONS[kind]:
        inputs = {ref: sha256_file(root / ref) for ref in d["layout"]}
        case = {"schema_version": "1.0", "case_id": d["case_id"], "driver_class": d["driver_class"],
                "source_sha256": sha256_bytes(canonical_json(inputs)),
                "requirements_sha256": sha256_file(root / d["requirements"]), "target_mcu": "HOST_ONLY",
                "compiler_version": clang, "compiler_flags": RUN_UNIT_FLAGS,
                "tool_versions": {"clang": clang, "python": sys.version.split()[0]}, "model_revision": None,
                "seed": None, "safety_profile": "HOST_DEMONSTRATOR_NOT_ASIL_EVIDENCE",
                "oracle_id": f"ORC-{d['case_id']}", "oracle_sha256": sha256_bytes(canonical_json(d["oracle"])),
                "input_refs": list(d["layout"]) or [d["harness"]], "holdout": kind == "holdout", "status": "FROZEN",
                "case_tags": d["tags"]}
        errs = list(_case_schema().iter_errors(case))
        if errs:
            raise ValueError(f"{d['case_id']}: {errs[0].message}")
        cases.append({"case": case, "harness": d["harness"], "harness_sha256": sha256_file(suite_dir / d["harness"]),
                      "layout": d["layout"], "input_sha256": inputs, "oracle": d["oracle"]})
    suite = {"schema_version": "1.0", "suite_id": f"forgec-cre-{kind}-v1", "holdout": kind == "holdout",
             "frozen_at": utc_now(), "cases": cases}
    SUITES[kind].write_text("# FROZEN CRE benchmark suite (protected path tests/reliability/**). Regenerate only with\n"
                            "# `python -m forge_factory.reliability.benchmark freeze` in a dedicated oracle-change "
                            "commit.\n" + yaml.safe_dump(suite, sort_keys=False, width=120))
    return suite


def load_suite(kind: str, path: Path | None = None) -> dict:
    return yaml.safe_load((path or SUITES[kind]).read_text())


def suite_sha256(*paths: Path) -> str:
    return sha256_bytes(b"".join(p.read_bytes() for p in paths))


def check_case(entry: dict, suite_dir: Path, root: Path = REPO_ROOT) -> str | None:
    """None if runnable; else INCOMPLETE:<why> (never substituted) or NOT_COMPUTABLE:<why> (environment drift)."""
    case = entry.get("case") or {}
    if list(_case_schema().iter_errors(case)):
        return "INCOMPLETE:CASE_SCHEMA"
    for k in ("compiler_version", "source_sha256", "oracle_sha256"):
        if not case.get(k):
            return f"INCOMPLETE:UNPINNED_{k.upper()}"
    if case["status"] != "FROZEN":
        return f"INCOMPLETE:STATUS_{case['status']}"
    if sha256_bytes(canonical_json(entry["oracle"])) != case["oracle_sha256"]:
        return "INCOMPLETE:ORACLE_TAMPERED"
    h = suite_dir / entry["harness"]
    if not h.is_file() or sha256_file(h) != entry["harness_sha256"]:
        return "INCOMPLETE:HARNESS_TAMPERED"
    for ref, want in entry["input_sha256"].items():
        if not (root / ref).is_file() or sha256_file(root / ref) != want:
            return f"INCOMPLETE:INPUT_TAMPERED:{ref}"
    if sha256_bytes(canonical_json(entry["input_sha256"])) != case["source_sha256"]:
        return "INCOMPLETE:SOURCE_HASH_MISMATCH"
    if _tool_version(["clang", "--version"]) != case["compiler_version"]:
        return "NOT_COMPUTABLE:COMPILER_VERSION_DRIFT"
    return None


def evaluate_oracle(oracle: dict, observed: dict) -> list[str]:
    fails = []
    for k, v in (oracle.get("equals") or {}).items():
        if observed.get(k) != v:
            fails.append(f"{k}={observed.get(k)!r}!={v!r}")
    for k, subs in (oracle.get("contains") or {}).items():
        blob = observed.get(k) or []
        for s in subs:
            if not any(s in str(x) for x in blob):
                fails.append(f"{k} lacks {s!r}")
    for k, v in (oracle.get("min") or {}).items():
        if not isinstance(observed.get(k), (int, float)) or observed[k] < v:
            fails.append(f"{k}={observed.get(k)!r}<{v}")
    return fails


def run_suite(kind: str, revision: str, pool: WorktreePool, store: CREStore | None = None,
              policy: Policy | None = None, suite_path: Path | None = None, root: Path = REPO_ROOT) -> dict:
    sp = suite_path or SUITES[kind]
    suite = load_suite(kind, sp)
    wt = pool.get(revision)
    rev = subprocess.run(["git", "rev-parse", "HEAD"], cwd=wt, capture_output=True, text=True).stdout.strip()
    results = []
    for entry in suite.get("cases") or []:
        cid = (entry.get("case") or {}).get("case_id", "?")
        t0 = time.monotonic()
        problem = check_case(entry, sp.parent, root)
        if problem:
            results.append({"case_id": cid, "status": problem.split(":")[0], "reason": problem, "observed": None})
            continue
        scratch = isolation.new_dir(f"cre-bench-{cid}")
        try:
            for ref, dst in entry["layout"].items():
                (scratch / "ws" / dst).parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(root / ref, scratch / "ws" / dst)
            (scratch / "ws").mkdir(exist_ok=True)
            isolation.hand_over("verifier", scratch)  # CRE-T049: harness runs as the verifier OS identity
            harness = sp.parent / entry["harness"]
            p = isolation.execute("verifier", [sys.executable, str(harness), str(scratch)], cwd=scratch,
                                  env=_env(wt, scratch), writable=[scratch], readable=[harness.parent], timeout=600)
            out = p.stdout.decode(errors="replace").strip().splitlines()
            try:
                observed = json.loads(out[-1])["observed"] if p.returncode == 0 and out else None
            except (ValueError, KeyError):
                observed = None
        finally:
            isolation.discard(scratch)
        if observed is None:
            tail = (p.stdout + p.stderr).decode(errors="replace").strip().splitlines()[-1:] or [""]
            results.append({"case_id": cid, "status": "ERROR", "reason": f"HARNESS_ERROR:{tail[0][:160]}",
                            "observed": None, "duration_s": round(time.monotonic() - t0, 2)})
            continue
        fails = evaluate_oracle(entry["oracle"], observed)
        results.append({"case_id": cid, "status": "FAIL" if fails else "PASS", "reason": "; ".join(fails)[:300] or None,
                        "observed": observed, "duration_s": round(time.monotonic() - t0, 2),
                        "output_sha256": sha256_bytes(p.stdout)})
    rec = {"suite_id": suite.get("suite_id"), "suite_sha256": suite_sha256(sp), "revision": rev,
           "run_at": utc_now(), "results": results, "n": len(results),
           "passed": sum(r["status"] == "PASS" for r in results), "model_tokens": 0}
    if store is not None:
        run_id = "br-" + sha256_bytes(f"{rec['suite_sha256']}|{rev}|{rec['run_at']}".encode())[:20]
        rec["run_id"] = run_id
        with store.conn() as c:
            c.execute("INSERT INTO cre_benchmark_runs VALUES (?,?,?,?,?)",
                      (run_id, rec["suite_sha256"], rev, canonical_json(rec).decode(), rec["run_at"]))
        if policy is not None:
            E.record(store, E.build("cre.benchmark_completed", run_id, {
                "suite": rec["suite_id"], "revision": rev[:12], "passed": rec["passed"], "n": rec["n"]},
                policy_sha256=policy.sha256, correlation_id=f"bench:{rev[:12]}", evidence_refs=[f"benchmark-run:{run_id}"]))
    return rec


def regressions(baseline: dict, candidate: dict) -> list[str]:
    """A case that passed on the baseline and does not pass on the candidate (any reason) is a regression."""
    cand = {r["case_id"]: r for r in candidate["results"]}
    return [f"{r['case_id']}:{cand.get(r['case_id'], {}).get('status', 'MISSING')}" for r in baseline["results"]
            if r["status"] == "PASS" and cand.get(r["case_id"], {}).get("status") != "PASS"]


def main(argv: list[str] | None = None) -> int:
    args = argv if argv is not None else sys.argv[1:]
    if args[:1] == ["freeze"]:
        for kind in args[1:] or list(SUITES):
            s = freeze(kind)
            print(f"frozen {s['suite_id']}: {len(s['cases'])} cases -> {SUITES[kind].relative_to(REPO_ROOT)}")
        return 0
    rev = args[0] if args else "HEAD"
    with WorktreePool() as pool:
        for kind in SUITES:
            rec = run_suite(kind, rev, pool)
            print(f"{rec['suite_id']} @ {rec['revision'][:12]}: {rec['passed']}/{rec['n']} PASS")
            for r in rec["results"]:
                print(f"  {r['case_id']} {r['status']} {r.get('reason') or ''}"[:160])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
